<div class="admin-page-heading"><div><span class="admin-eyebrow">ENQUIRY <?= e($enquiry['reference_code']) ?></span><p>Received <?= e(format_date($enquiry['created_at'])) ?></p></div><a class="admin-text-link" href="<?= e(url('/admin/enquiries')) ?>">← All enquiries</a></div><div class="enquiry-detail-grid"><section class="admin-panel enquiry-message"><span class="admin-eyebrow">PROJECT DESCRIPTION</span><h2><?= e($enquiry['full_name']) ?></h2><p><?= nl2br(e($enquiry['message'])) ?></p><?php if($enquiry['attachment_path']): ?><p class="muted-admin">An image attachment was supplied. It is stored privately and is not exposed through a public URL.</p><?php endif; ?></section><section class="admin-panel enquiry-data"><span class="admin-eyebrow">CLIENT DETAILS</span><dl><dt>Phone</dt><dd><a href="tel:<?= e($enquiry['phone']) ?>"><?= e($enquiry['phone']) ?></a></dd><dt>Email</dt><dd><?= $enquiry['email']?'<a href="mailto:'.e($enquiry['email']).'">'.e($enquiry['email']).'</a>':'—' ?></dd><dt>Location</dt><dd><?= e($enquiry['location']?:'—') ?></dd><dt>Property type</dt><dd><?= e($enquiry['property_type']?:'—') ?></dd><dt>Service</dt><dd><?= e($enquiry['service_type']?:'—') ?></dd><dt>Project size</dt><dd><?= e($enquiry['project_size']?:'—') ?></dd><dt>Preferred date</dt><dd><?= e($enquiry['preferred_date']?:'—') ?></dd></dl><form method="post" action="<?= e(url('/admin/enquiries/'.$enquiry['id'].'/status')) ?>" class="status-update-form"><?= csrf_field() ?><label for="status">Update status</label><select name="status" id="status"><?php foreach(['pending','contacted','quoted','in_progress','completed','closed'] as $status): ?><option value="<?= e($status) ?>" <?= $enquiry['status']===$status?'selected':'' ?>><?= e(ucwords(str_replace('_',' ',$status))) ?></option><?php endforeach; ?></select><button class="admin-button" type="submit">Save Status <span>→</span></button></form></section></div>
